def device(slug, name, short, family, title, description, h1, lead, answer, intro, models, quirk_title, quirk,
           faq, related, card, apps=None, extra=None, steps_override=None):
    fam = FAM[family]
    model_head = ['Modell / Serie', 'System', 'IPTV']
    sections = [
        ('system', f'Welches System nutzt {short}?', f'<p>{intro}</p>' + table(model_head, models, f'{short} Modelle und Systeme') + (CHECK_OS if family in ('google', 'vidaa', 'limited', 'fire') else '')),
        ('apps', f'Beste IPTV App für {short}', f'<p>Welche Apps auf {short} laufen, hängt vom System ab. Diese Lösungen sind für {fam["label"]} geeignet und unterstützen Xtream Codes, M3U oder Portal-Zugänge:</p>'
         + table(['App', 'Bezugsquelle', 'Stärke'], apps or fam['apps'], f'IPTV Apps für {short}')
         + '<p>Alle Player sind leere Abspielprogramme: Sender, Filme und Serien kommen aus Ihrem IPTV-Zugang. Einen Überblick über alle Apps gibt die <a href="/iptv-apps/">IPTV-App-Übersicht</a>.</p>'),
        ('anleitung', f'IPTV auf {short} einrichten: Schritt für Schritt', steps(*(steps_override or fam['steps']))),
        (f'quirk', quirk_title, quirk),
        ('einstellungen', f'Die besten Einstellungen für IPTV auf {short}', checks(*fam['settings'])),
        ('probleme', f'IPTV auf {short} funktioniert nicht? Lösungen', table(['Problem', 'Lösung'], fam['problems'], f'{short} IPTV Probleme') + LOGIN),
    ]
    if extra:
        sections.insert(4, extra)
    return dict(slug=slug, parent='geraete', kind='guide', title=title, description=description, eyebrow='GERÄTE-ANLEITUNG',
                h1=h1, lead=lead, answer=answer, sections=sections, faq=faq, related=related, card=card)


